dataTableFormat:
{
  "is multi section": "true",
  "sections": [
    {
      "section id": "falcon_gene",
      "header": "Which human phenotypes are connected to $gene, and which variants drive that connection?",
      "data point": {
        "type": "api",
        "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/query/4dn-falcon-gene?q=$gene",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "search parameters": [
        {
          "parameter": "gene",
          "label": "Gene",
          "values": "kp genes",
          "type": "input"
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "P-value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "P-value(-log10)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "Probability",
            "raw field": "pip"
          },
          {
            "type": "raw",
            "field name": "Standard error",
            "raw field": "stdErr"
          },
          {
            "type": "join multi",
            "field name": "V2G link score",
            "fields to join": [
              "Phenotype",
              "Gene"
            ],
            "join by": [
              ","
            ]
          }
        ],
        "top rows": [
          "Phenotype",
          "P-value",
          "Beta",
          "Probability",
          "Standard error",
          "V2G link score"
        ],
        "tool tips": {
          "Phenotype": "The specific disease, trait, or biological measurement being analyzed (e.g., LDL cholesterol, Alzheimer's disease).",
          "P-value": "Measures the statistical significance of the association. A lower p-value indicates stronger evidence that the observed association is not a result of random chance.",
          "Beta": "The estimated magnitude and direction of the gene's effect on the phenotype. This value is calculated following a heuristic similar to how burden calculates effects. Direction: A positive beta suggests the gene increases the trait value, while a negative beta suggests it decreases it. Magnitude: The size of the number indicates the strength of the effect. Numbers further from zero imply a stronger impact.",
          "Probability": "The core 'genetic support' score from FALCON, representing the posterior probability that the gene is associated with the trait. Values range from 0 to 1. Scores closer to 1 indicates higher confidence from the model that the gene plays a role in the phenotype.",
          "Standard error": "Quantifies the precision of the Beta estimate. A smaller standard error indicates a more precise and reliable estimate of the gene's effect size.",
          "V2G link score": "Click 'Show' to see which specific variants (hg19 coordinates) are driving the gene's association score and FALCON's confidence in each variant-to-gene connection. 'Link probability' indicates the Posterior Linkage Probability calculated by FALCON and quantifies the model's confidence that this specific variant is functionally linked to the gene of interest. Scores range from 0 to 1. A value closer to 1 indicates a more confident link between the variant and the gene, suggesting this variant likely exerts its effect on the trait through that gene. This output is a key part of FALCON's 'fine-linking' capabilities."
        },
        "column formatting": {
          "Phenotype": {
            "type": [
              "kp phenotype description"
            ]
          },
          "V2G link score": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/",
                "index": "4dn-falcon-v2g",
                "parameters": [
                  "phenotype",
                  "gene"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "rsID",
                    "raw field": "rsID"
                  },
                  {
                    "type": "raw",
                    "field name": "Variant ID",
                    "raw field": "varID"
                  },
                  {
                    "type": "raw",
                    "field name": "Link probability",
                    "raw field": "value"
                  }
                ],
                "top rows": [
                  "Variant ID",
                  "rsID",
                  "Link probability"
                ],
                "column formatting": {
                  "Link probability": {
                    "type": [
                      "scientific notation"
                    ]
                  }
                }
              }
            }
          },
          "P-value": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "Probability": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard error": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "visualizers": {
        "wrapper type": "tabs",
        "visualizers": [
          {
            "label": "P-value",
            "type": "phewas plot",
            "group by": "Gene",
            "y axis field": "P-value(-log10)",
            "convert y -log10": null,
            "y ticks decimal point": "2",
            "render by": "Phenotype",
            "y axis label": "P-value(-log10)",
            "x axis label": "Phenotype",
            "beta field": null,
            "hover content": [
              "Phenotype",
              "P-value",
              "Beta",
              "Probability",
              "Standard error"
            ],
            "thresholds": [
              8
            ],
            "label in black": "greater than",
            "height": 300,
            "plot margin": {
              "top": 50,
              "bottom": 200,
              "left": 150,
              "right": 175
            }
          },
          {
            "label": "Probability",
