              "right": 175
            }
          },
          {
            "label": "P-value vs Probability",
            "type": "scatter plot",
            "star key": null,
            "render type": "single plot",
            "group by": "Gene",
            "color by": "Gene",
            "y axis field": "P-value(-log10)",
            "y axis label": "P-value(-log10)",
            "x axis field": "Probability",
            "x axis label": "Probability",
